const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const creditIcon='<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="3" stroke="currentColor" stroke-width="1.7"/><circle cx="12" cy="12" r="4" stroke="currentColor" stroke-width="1.7"/><path d="M6 6h2M16 18h2" stroke="currentColor" stroke-width="1.7"/></svg>';
export function renderCredits({config,wallet,user,error='',notice='',busy=false,tab='buy',selected}){
 const test=config.walletMode==='test',packs=config.creditPacks||[];
 const tabs=[['buy','Buy Credits Now!'],['auto','Auto-Reload Credits'],['free','Claim Free Credits']];
 const buy=`<div class="credits-packs" role="radiogroup" aria-label="Credit bundles">${packs.map(p=>`<label class="credits-pack ${p.credits===selected?'is-selected':''}"><input type="radio" name="credits-pack" ${busy?'disabled':''} value="${p.credits}" ${p.credits===selected?'checked':''}><span>${Number(p.credits).toLocaleString('en-US')} Credits</span><span class="credits-price">${new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(p.amount/100)}</span></label>`).join('')}</div><section class="credits-policy"><h2>Payment &amp; Refund Information</h2><ul><li>Credit bundles are one-time purchases in USD. Your final total is shown before payment.</li><li>You will continue to Stripe’s secure checkout to pay, then return here. Credits are added after payment is confirmed.</li><li>For a payment or refund question, keep your Stripe receipt and contact the site owner.</li></ul></section><div class="credits-checkout-bar"><button class="credits-buy" data-buy-selected ${busy||!config.payments||!selected?'disabled':''}>${busy?'<span class="credits-spinner" aria-hidden="true"></span> Opening checkout…':test?'Test Checkout':'Buy Now'}</button></div>`;
 const free=`<div class="credits-free-card"><span class="credits-badge">Daily check-in</span><h2>Check in daily for 100 Credits</h2><p>You can only check in once per day to claim bonus Credits.</p>${user?`<button class="credits-small-button" data-checkin ${busy||!config.walletConfigured||wallet?.checked?'disabled':''}>${wallet?.checked?'Checked in today':'Check in'}</button>`:'<button class="credits-small-button" data-action="login">Sign in to check in</button>'}</div><section class="credits-faq"><h2>FAQ</h2><h3>Q. What are credits?</h3><p>Your credit balance is saved to your account. Chat currently does not deduct credits.</p><h3>Q. When can I check in again?</h3><p>Daily check-in resets at 00:00, Shanghai time.</p><h3>Q. Can I transfer credits to another account?</h3><p>Credits are associated with the account used at checkout.</p></section>`;
 const auto=`<div class="credits-auto-options"><span>Low Balance</span><span>Monthly</span></div><div class="credits-free-card"><h2>Auto-Reload Credits</h2><p>Automatic recurring purchases are not enabled for this site yet. You can buy a one-time Credit bundle without starting a subscription.</p><button class="credits-small-button" data-credit-tab="buy">Buy Credits</button></div>`;
 return `<div class="credits-page" aria-busy="${busy}"><header class="credits-header"><a href="/" aria-label="Back to stories">‹</a><h1>My Credit</h1><button data-credit-info aria-label="About Credits">ⓘ</button></header><div class="credits-content"><button class="credits-balance" data-credit-history>${creditIcon}<span>${wallet?Number(wallet.balance).toLocaleString('en-US'):'—'}</span><span class="credits-history-label">Credit History <span aria-hidden="true">›</span></span></button><button class="credits-auto-banner" data-credit-tab="auto">Explore Auto-Reload Credits<span aria-hidden="true">›</span></button>${test?'<p class="credits-environment">Test environment · no real payment</p>':''}<nav class="credits-tabs" role="tablist" aria-label="Credits">${tabs.map(([id,label])=>`<button role="tab" id="credits-tab-${id}" aria-controls="credits-panel" aria-selected="${tab===id}" tabindex="${tab===id?0:-1}" data-credit-tab="${id}">${label}</button>`).join('')}</nav><div class="credits-status" role="${error?'alert':'status'}" ${!error&&!notice?'hidden':''}>${esc(error||notice)}</div>${!user?'<div class="credits-signin"><button data-action="login">Sign in to view your balance</button></div>':''}${!config.payments&&tab==='buy'?'<p class="credits-status">Credit purchases are not available yet.</p>':''}<div class="credits-panel" role="tabpanel" id="credits-panel" aria-labelledby="credits-tab-${tab}">${tab==='free'?free:tab==='auto'?auto:buy}</div><div class="credits-account-actions">${user?`<button data-wallet-refresh ${busy?'disabled':''}>Refresh balance</button>`:''}</div></div></div>`;
}
